import { Command } from "commander";
import { apiClient } from "../http.js";
import { printJson, printTable } from "../output.js";

type Invoice = {
  id: string;
  number: string;
  clientName: string;
  status: "draft" | "open" | "paid" | "void";
  totalCents: number;
  currency: string;
  dueAt: string | null;
};

export const invoicesCommand = new Command("invoices").description("Work with invoices");

invoicesCommand
  .command("list")
  .description("List invoices in the current org")
  .option("--json", "print machine-readable JSON instead of a table")
  .action(async (opts: { json?: boolean }) => {
    const client = await apiClient();
    const res = await client.get<{ data: Invoice[] }>("/v1/invoices");
    if (opts.json) {
      printJson(res.data.data);
      return;
    }
    const rows = res.data.data.map((i) => [i.number, i.clientName, i.status, i.dueAt ?? "-"]);
    printTable(["NUMBER", "CLIENT", "STATUS", "DUE"], rows);
  });

