export type WebhookJob = { endpointUrl: string; secret: string; event: string; payload: unknown };

export async function deliverWebhook(job: Job<WebhookJob>): Promise<void> {
  const body = JSON.stringify({ event: job.data.event, data: job.data.payload });
  const res = await http.post(job.data.endpointUrl, body, {
    headers: { "content-type": "application/json", "x-acme-signature": signPayload(body, job.data.secret) },
  });
  logger.info({ jobId: job.id, status: res.status }, "webhook delivered");
}

